extra_style='''<style id="majalis-v1140-footer-ballot-closing">\n.site-footer-wrap{position:relative}\n.site-footer-wrap .footer{position:relative;display:flex;align-items:center;justify-content:center;gap:10px 14px;flex-wrap:wrap;min-height:42px;padding-inline:118px}\n.site-footer-wrap .footer-admin-entry{position:absolute;inset-inline-start:14px;top:50%;transform:translateY(-50%);margin:0;white-space:nowrap}\n.minutes-closing-fields{grid-column:1/-1;border:1px solid var(--line);border-radius:14px;background:var(--soft);padding:13px}\n.minutes-closing-fields>strong{display:block;color:var(--navy);font-size:13px;margin-bottom:9px}\n.minutes-closing-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.minutes-closing-sign-toggle{align-self:end;min-height:45px;border:1px solid var(--line);border-radius:11px;background:#fff;padding:9px 11px}\n.minutes-final-block{margin:24px auto 8px;width:min(100%,430px);border-top:1px solid var(--line);padding-top:14px}\n.minutes-final-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 18px}\n.minutes-final-item{min-height:48px}.minutes-final-item span{display:block;color:var(--muted);font-size:9px}.minutes-final-item strong{display:block;color:var(--navy);font-size:11px;margin-top:2px}.minutes-final-signature{grid-column:1/-1}.minutes-final-signature .sign-pad{display:block;height:42px;border-bottom:1px solid #9FA8B4}\n.minutes-default-closing{text-align:center;font-weight:700;color:var(--navy);margin:24px 0 10px;font-size:13px}\n.blank-ballot-note{text-align:center;color:var(--muted);font-size:10px;margin:0 0 10px}\n.blank-ballot-card .ballot-person{display:none!important}\n@media(max-width:760px){.site-footer-wrap .footer{padding-inline:12px;padding-bottom:48px}.site-footer-wrap .footer-admin-entry{top:auto;bottom:4px;inset-inline-start:10px;transform:none}.minutes-closing-grid{grid-template-columns:1fr}}\n@media print{.site-footer-wrap{display:none!important}}\n</style>\n'''
