old_ballot="function ballotParticipantCard(person,index,items){const p=person?normalizeParticipant(person):null;const name=p?.name||'',role=p?.role||'',votes=p?participantVoteTotal(p):0;const participantMeta=`<div class=\"ballot-person\"><div><span>اسم المصوت</span><strong>${esc(name)||'____________________________'}</strong></div><div><span>الصفة</span><strong>${esc(role)||'____________________________'}</strong></div>${ownershipRegisterEnabled()?`<div><span>عدد الأصوات</span><strong class=\"latin-number\">${votes||'________________'}</strong></div><div><span>النسبة من إجمالي حقوق التصويت</span><strong class=\"latin-number\">${percentText(votes,capitalVotesTotal())}</strong></div>`:''}</div>`;const rows=items.length?items.map((item,i)=>`<tr><td>${i+1}</td><td><strong>${esc(item.title||'')}</strong>${item.decision?`<div class=\"ballot-decision\"><strong>القرار المقترح:</strong> ${esc(item.decision)}</div>`:''}</td><td><span class=\"vote-choice\"><span class=\"choice-box\"></span> موافق</span></td><td><span class=\"vote-choice\"><span class=\"choice-box\"></span> غير موافق</span></td><td><span class=\"vote-choice\"><span class=\"choice-box\"></span> ممتنع</span></td></tr>`).join(''):`<tr><td>1</td><td></td><td><span class=\"choice-box\"></span></td><td><span class=\"choice-box\"></span></td><td><span class=\"choice-box\"></span></td></tr>`;return `<section class=\"ballot-card individual-attendance-sheet\">${participantMeta}<table class=\"doc-table ballot-table\"><thead><tr><th>م</th><th>البند محل التصويت</th><th>موافق</th><th>غير موافق</th><th>ممتنع</th></tr></thead><tbody>${rows}</tbody></table><div class=\"signature-grid single-signature-grid\"><div class=\"signature-field\">توقيع المصوت<span class=\"sign-pad\"></span></div></div></section>`}"
new_ballot="function ballotParticipantCard(person,index,items){const p=person?normalizeParticipant(person):null,blank=!p;const name=p?.name||'',role=p?.role||'',votes=p?participantVoteTotal(p):0;const participantMeta=blank?'':`<div class=\"ballot-person\"><div><span>اسم المصوت</span><strong>${esc(name)}</strong></div><div><span>الصفة</span><strong>${esc(role)}</strong></div>${ownershipRegisterEnabled()?`<div><span>عدد الأصوات</span><strong class=\"latin-number\">${votes||0}</strong></div><div><span>النسبة من إجمالي حقوق التصويت</span><strong class=\"latin-number\">${percentText(votes,capitalVotesTotal())}</strong></div>`:''}</div>`;const rows=items.length?items.map((item,i)=>`<tr><td>${i+1}</td><td><strong>${esc(item.title||'')}</strong>${item.decision?`<div class=\"ballot-decision\"><strong>القرار المقترح:</strong> ${esc(item.decision)}</div>`:''}</td><td><span class=\"vote-choice\"><span class=\"choice-box\"></span> موافق</span></td><td><span class=\"vote-choice\"><span class=\"choice-box\"></span> غير موافق</span></td><td><span class=\"vote-choice\"><span class=\"choice-box\"></span> ممتنع</span></td></tr>`).join(''):`<tr><td>1</td><td></td><td><span class=\"choice-box\"></span></td><td><span class=\"choice-box\"></span></td><td><span class=\"choice-box\"></span></td></tr>`;return `<section class=\"ballot-card individual-attendance-sheet ${blank?'blank-ballot-card':''}\">${blank?'<p class=\"blank-ballot-note\">بطاقة تصويت فارغة للاستخدام الورقي</p>':''}${participantMeta}<table class=\"doc-table ballot-table\"><thead><tr><th>م</th><th>البند محل التصويت</th><th>موافق</th><th>غير موافق</th><th>ممتنع</th></tr></thead><tbody>${rows}</tbody></table>${blank?'':`<div class=\"signature-grid single-signature-grid\"><div class=\"signature-field\">توقيع المصوت<span class=\"sign-pad\"></span></div></div>`}</section>`}"
if old_ballot not in s: raise SystemExit('ballot function anchor missing')
s=s.replace(old_ballot,new_ballot,1)
s=s.replace("document.querySelectorAll('#docVoting .ballot-card').forEach(card=>{", "document.querySelectorAll('#docVoting .ballot-card:not(.blank-ballot-card)').forEach(card=>{", 1)

helper="""function minutesFinalBlock(){const name=($('minutesClosingName')?.value||'').trim(),position=($('minutesClosingPosition')?.value||'').trim(),date=($('minutesClosingDate')?.value||'').trim(),signature=!!$('minutesClosingSignature')?.checked;if(!name&&!position&&!date&&!signature)return '';const items=[];if(name)items.push(`<div class=\"minutes-final-item\"><span>الاسم</span><strong>${esc(name)}</strong></div>`);if(position)items.push(`<div class=\"minutes-final-item\"><span>المنصب</span><strong>${esc(position)}</strong></div>`);if(date)items.push(`<div class=\"minutes-final-item\"><span>التاريخ</span><strong>${esc(date)}</strong></div>`);if(signature)items.push(`<div class=\"minutes-final-item minutes-final-signature\"><span>التوقيع</span><span class=\"sign-pad\"></span></div>`);return `<section class=\"minutes-final-block\"><div class=\"minutes-final-grid\">${items.join('')}</div></section>`}\nfunction defaultClosingLine(){return '<div class=\"minutes-default-closing\">والله الموفق</div>'}\n"""
if 'function renderDocuments(){' not in s: raise SystemExit('renderDocuments anchor missing')
s=s.replace('function renderDocuments(){',helper+'function renderDocuments(){',1)

minutes_old="${closingNoteLine}${endLine}</div>`+footer();"
