idle_code="""const emitState=(state,label)=>window.dispatchEvent(new CustomEvent('majalis:voice-state',{detail:{state,label}}));\nfunction clearIdleTimer(){clearTimeout(idleTimer);idleTimer=null}\nfunction markVoiceActivity(){lastVoiceActivity=Date.now();if(!active)return;clearIdleTimer();idleTimer=setTimeout(()=>{if(active&&Date.now()-lastVoiceActivity>=VOICE_IDLE_TIMEOUT_MS)stop('idle')},VOICE_IDLE_TIMEOUT_MS)}\n"""
