v=v.replace("if(content.inputTranscription?.text&&!micSuppressed)setDetail(`أنت: ${content.inputTranscription.text}`);", "if(content.inputTranscription?.text&&!micSuppressed){markVoiceActivity();setDetail(`أنت: ${content.inputTranscription.text}`)}",1)
v=v.replace("if(content.outputTranscription?.text)setDetail(`مساعد مجالس: ${content.outputTranscription.text}`);", "if(content.outputTranscription?.text){markVoiceActivity();setDetail(`مساعد مجالس: ${content.outputTranscription.text}`)}",1)
v=v.replace("function playPcm(base64){if(!active||!outputContext||!outputWorklet||!base64)return;", "function playPcm(base64){if(!active||!outputContext||!outputWorklet||!base64)return;markVoiceActivity();",1)
v=v.replace("async function shutdown(){await releaseWakeLock();clearTimeout(resumeMicTimer);", "async function shutdown(){clearIdleTimer();await releaseWakeLock();clearTimeout(resumeMicTimer);",1)
v=v.replace("if(!active)return;startMic();setStatus('أسمعك الآن','listening');", "if(!active)return;startMic();markVoiceActivity();setStatus('أسمعك الآن','listening');",1)
old_stop="async function stop(){active=false;try{session?.close?.()}catch{}session=null;await shutdown();emitState('','اضغط وقل ما تريد');const host=document.getElementById('majalisVoiceOverlay');if(host)host.hidden=true}"
new_stop="async function stop(reason='manual'){const idle=reason==='idle';active=false;clearIdleTimer();try{session?.close?.()}catch{}session=null;await shutdown();emitState('',idle?'انتهت المحادثة لعدم وجود تفاعل':'اضغط وقل ما تريد');const host=document.getElementById('majalisVoiceOverlay');if(host){if(idle){setStatus('تم إنهاء المحادثة','idle');setDetail('انتهت المحادثة الصوتية بعد 30 ثانية بدون تفاعل.');setTimeout(()=>{if(!active)host.hidden=true},2200)}else host.hidden=true}}"
if old_stop not in v: raise SystemExit('voice stop anchor missing')
v=v.replace(old_stop,new_stop,1)
VOICE.write_text(v)
